import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import toast from 'react-hot-toast';
import { useAuth } from '../context/AuthContext';
import './AptitudeTest.css';

const AptitudeTest = () => {
    const [questions, setQuestions] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [answers, setAnswers] = useState({});
    const [timeLeft, setTimeLeft] = useState(600); // 10 minutes (600 seconds)
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [result, setResult] = useState(null);

    const navigate = useNavigate();
    const { isAuthenticated } = useAuth();

    useEffect(() => {
        fetchQuestions();
    }, []);

    // Timer effect
    useEffect(() => {
        if (loading || result || submitting) return;

        const timerId = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    clearInterval(timerId);
                    handleSubmitQuiz(); // Automatically submit when time is up
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(timerId);
    }, [loading, result, submitting]);

    const fetchQuestions = async () => {
        try {
            const response = await axios.get('http://localhost:5000/api/quiz/start', { withCredentials: true });
            if (response.data.success) {
                setQuestions(response.data.data);
            }
        } catch (error) {
            console.error('Error fetching questions:', error);
            toast.error('Failed to load quiz. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const handleOptionSelect = (questionId, optionId) => {
        setAnswers(prev => ({
            ...prev,
            [questionId]: optionId
        }));
    };

    const handleNext = () => {
        if (currentIndex < questions.length - 1) {
            setCurrentIndex(prev => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentIndex > 0) {
            setCurrentIndex(prev => prev - 1);
        }
    };

    const handleSubmitQuiz = async () => {
        if (!isAuthenticated) {
            toast.error('Please login to save your results.');
            return;
        }

        setSubmitting(true);
        const formattedAnswers = Object.entries(answers).map(([questionId, optionId]) => ({
            question_id: parseInt(questionId),
            selected_option_id: parseInt(optionId)
        }));

        try {
            const response = await axios.post('http://localhost:5000/api/quiz/submit',
                { answers: formattedAnswers },
                { withCredentials: true }
            );

            if (response.data.success) {
                toast.success('Quiz submitted successfully!');
                navigate('/aptitude-results', { state: { result: response.data.data } });
            }
        } catch (error) {
            console.error('Submission error:', error);
            toast.error('Failed to submit quiz.');
        } finally {
            setSubmitting(false);
        }
    };

    const formatTime = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    if (loading) {
        return (
            <div className="test-loading">
                <div className="spinner"></div>
                <p>Loading your personalized aptitude test...</p>
            </div>
        );
    }

    if (result) {
        return (
            <div className="test-results-container">
                <h2>Quiz Results</h2>
                <div className="result-card">
                    <div className="score-circle">
                        <span>{result.score}/{result.total_questions}</span>
                        <p>{result.percentage}</p>
                    </div>

                    <div className="category-insights">
                        <div className="insight strength">
                            <h3>🌟 Top Strength</h3>
                            <p>{result.strength_category || 'N/A'}</p>
                        </div>
                        <div className="insight weakness">
                            <h3>🎯 Area to Improve</h3>
                            <p>{result.weak_category || 'N/A'}</p>
                        </div>
                    </div>

                    <div className="breakdown">
                        <h3>Detailed Breakdown</h3>
                        {Object.entries(result.category_breakdown).map(([cat, stats]) => (
                            <div key={cat} className="breakdown-item">
                                <span>{cat}</span>
                                <div className="progress-bg">
                                    <div
                                        className="progress-fill"
                                        style={{ width: `${(stats.correct / stats.total) * 100}%` }}
                                    ></div>
                                </div>
                                <span>{stats.correct}/{stats.total}</span>
                            </div>
                        ))}
                    </div>

                    <button className="btn-primary" onClick={() => navigate('/dashboard')}>
                        Go to Dashboard
                    </button>
                </div>
            </div>
        );
    }

    if (questions.length === 0) {
        return <div className="test-empty">No questions available at the moment.</div>;
    }

    const currentQuestion = questions[currentIndex];
    const progressPercentage = ((currentIndex + 1) / questions.length) * 100;

    return (
        <div className="aptitude-test-container">
            <div className="test-header">
                <div className="header-info">
                    <h2>Aptitude Test</h2>
                    <span className="category-badge">{currentQuestion.category_name}</span>
                </div>
                <div className={`timer ${timeLeft < 60 ? 'timer-warning' : ''}`}>
                    ⏱ {formatTime(timeLeft)}
                </div>
            </div>

            <div className="progress-container">
                <div className="progress-bar">
                    <div className="progress-fill" style={{ width: `${progressPercentage}%` }}></div>
                </div>
                <span className="progress-text">Question {currentIndex + 1} of {questions.length}</span>
            </div>

            <div className="question-card">
                <h3 className="question-text">{currentQuestion.question_text}</h3>

                <div className="options-grid">
                    {currentQuestion.options.map(option => (
                        <div
                            key={option.id}
                            className={`option-item ${answers[currentQuestion.id] === option.id ? 'selected' : ''}`}
                            onClick={() => handleOptionSelect(currentQuestion.id, option.id)}
                        >
                            <span className="option-text">{option.option_text}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className="test-navigation">
                <button
                    className="btn-secondary"
                    onClick={handlePrev}
                    disabled={currentIndex === 0}
                >
                    Previous
                </button>

                {currentIndex === questions.length - 1 ? (
                    <button
                        className="btn-submit"
                        onClick={handleSubmitQuiz}
                        disabled={submitting || Object.keys(answers).length < questions.length}
                    >
                        {submitting ? 'Submitting...' : 'Submit Quiz'}
                    </button>
                ) : (
                    <button
                        className="btn-primary"
                        onClick={handleNext}
                    >
                        Next
                    </button>
                )}
            </div>
        </div>
    );
};

export default AptitudeTest;
